  countersign: {
    parameters: {
      query?: never;
      header: {
        "idempotency-key": string;
      };
      path?: never;
      cookie?: never;
    };
    requestBody: {
      content: {
        "application/json": components["schemas"]["CountersignRequest"];
      };
    };
    responses: {
      /** @description The decision and its countersignatures */
      200: {
        headers: {
          /** @description `degraded` when only one TEE signed; the same as `mode` in the body. */
          "Keelson-Countersign-Mode": "2of2" | "degraded";
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Countersigned"];
        };
      };
      /** @description Countersigned, and a step of the purchase is still pending; `Location` is the purchase, which finishes on its own */
      202: {
        headers: {
          Location: string;
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Countersigned"];
        };
      };
      /** @description A leg refused the agent's authority */
      401: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description No such mandate of an operator this client linked, or that the user approved for this app */
      404: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description The mandate is not active, the evidence root is not stored for it or already binds another purchase, the request was already used, or the same cart is already being bought (`purchase-exists`, with its `purchaseId`) */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description A leg refused the request as too large */
      413: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description The request is invalid, the purchase unit's amount does not reconcile with the cart (`invalid-amount`), the authorization is not this purchase's hold, the cart is not the one held for this request, the evidence holds another cart or another checkout amount, its Channel3 observation is not usable, its WebFact is not this purchase's, or a live store is not the website the mandate allows */
      422: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description Too many countersigns for this mandate */
      429: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description The legs disagree, or a signer is not registered */
      502: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
      /** @description A leg needed to sign, or PayPal, is unavailable, or the hosted operator's key is not configured */
      503: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": components["schemas"]["Problem"];
        };
      };
    };
  };
